// Источник: web-тест .qa/e2e/tests/home/hm-01-daily-home.spec.ts, план .qa/e2e/specs/home.md, кейс .qa/tests/home/HM-01-daily-home.md
// Тикеты #6a86f7ea · 23d9ba93535f «פיתוח: מסך בית יומי עם התפילה הקרובה»; #6aa7ca27 · 64c76883f464; #6a9fdd33 · 207781fc0813.
// Опора: F-98 AC1–AC6 · S-01, S-10. Аккаунт user1 («אקדא טסט»).
// URL табов → признак экрана: «תפילות» — строка о нусахе профиля, «בית» — «התחל תפילה», «המסע שלי» — «דרגה N מתוך M»;
// «תהילים» и «ברכות» — главная скрыта (признак экрана не подтверждён web-тестами; aria-selected не переносится).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, byLabelStartsWith, tapLabel, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, goTab, TABS } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const PRAYERS: Record<string, string> = { 'שחרית': 'shacharit', 'מנחה': 'mincha', 'ערבית': 'arvit' };
const NUSACH: Record<string, string> = { 'אשכנז': 'ashkenaz', 'ספרד': 'sfarad' };

/** «התחל תפילה»: активна — нажать; неактивна вне окна молитвы («… מתחילה ב-HH:MM», норма) — открыть ту же молитву из «תפילות». */
async function startNearestPrayer() {
  const start = await byLabel('התחל תפילה');
  await start.waitForDisplayed({ timeout: 20000 });
  if (await start.isEnabled()) { await start.click(); return; }
  const startsAt = await byTextMatches('.*מתחילה ב-?\\s?\\d{1,2}:\\d{2}.*');
  await expect(startsAt).toBeDisplayed();
  const line = await startsAt.getText();
  const prayer = Object.keys(PRAYERS).find((p) => line.includes(p));
  const nusach = (await (await byTextMatches('.*נוסח (אשכנז|ספרד).*')).getText()).match(/נוסח (אשכנז|ספרד)/)?.[1];
  expect(prayer).toBeTruthy();
  expect(nusach).toBeTruthy();
  await openPrayer(`${PRAYERS[prayer!]}_${NUSACH[nusach!]}`, prayer!);
}

describe('Главная', () => {
  afterEach(async () => { await toHome(); });

  it('HM-01 Главная: приветствие с именем, дата, ближайшая молитва, счётчики, навигация из 5 табов #6a86f7ea @prod-safe', async () => {
    // 1. Главная.
    await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });

    // 2. Шапка, карточка молитвы, счётчики, секции, нижняя навигация.
    await expect(byLabel('מעבר לפרטים שלי')).toBeDisplayed();
    await expect(byTextContains('אקדא טסט')).toBeDisplayed();
    await expect(byTextMatches('.*טוב(ים)? אקדא טסט.*')).toBeDisplayed();
    await expect(byTextContains('תשפ״ז')).toBeDisplayed();
    await expect(byLabel('זמני התפילות של היום')).toBeDisplayed();
    await expect(byTextMatches('.*\\d{2}:\\d{2} - \\d{2}:\\d{2}.*')).toBeDisplayed();
    await expect(byTextMatches('נוסח .*')).toBeDisplayed();
    await expect(byLabelStartsWith('ימים רצופים: ')).toBeDisplayed();
    await expect(byLabelStartsWith('תפילות היום: ')).toBeDisplayed();
    await expect(byLabelStartsWith('סה״כ תפילות: ')).toBeDisplayed();
    expect(await (await byLabelStartsWith('סה״כ תפילות: ')).getAttribute(driver.isAndroid ? 'content-desc' : 'name')).toMatch(/^סה״כ תפילות: \d+$/);
    for (const tab of TABS) await expect(byText(tab)).toBeDisplayed();
    await scrollToText('תזכורות מהירות');
    await expect(byText('תזכורות מהירות')).toBeDisplayed();
    await scrollToText('תאריכים חשובים');
    await expect(byText('תאריכים חשובים')).toBeDisplayed();

    // 3. «התחל תפילה» → молитва в נוסח אשכנז; «חזרה» → главная.
    await toHome();
    await startNearestPrayer();
    await expect(byTextContains('(אשכנזי)')).toBeDisplayed();
    await tapLabel('חזרה');
    await expect(byLabel('התחל תפילה')).toBeDisplayed();

    // 4. Каждый таб нижней навигации открывает свой экран.
    await goTab('תהילים');
    await expect(byLabel('התחל תפילה')).not.toBeDisplayed();
    await goTab('תפילות');
    await expect(byText('התפילות מוצגות בנוסח אשכנז שנשמר בפרופיל.')).toBeDisplayed();
    await goTab('בית');
    await expect(byLabel('התחל תפילה')).toBeDisplayed();
    await goTab('המסע שלי');
    await (await byTextMatches('.*דרגה \\d+ מתוך \\d+.*')).waitForDisplayed({ timeout: 20000 });
    await goTab('ברכות');
    await expect(byLabel('התחל תפילה')).not.toBeDisplayed();
    await expect(byTextMatches('.*דרגה \\d+ מתוך \\d+.*')).not.toBeDisplayed();
  });
});
